import {workspaceAt,assertWorkspaceStep} from './scenario.mjs';
import {clone,quoteLines,quoteTotal,validateQuote,saveQuote,approveQuote,publishProposal,reviseQuote,addComment} from '../application/domain.mjs';
import {addFinding,updateDealDetails} from '../application/deal-domain.mjs';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'Pending':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const assets='../application/assets/';
const image=(file,alt,cls='')=>`<img class="${cls}" src="${assets}${file}" alt="${esc(alt)}">`;
const paths={arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',chat:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',save:'M5 3h12l3 3v15H4V3z M8 3v6h8V3 M8 21v-8h8v8',plus:'M12 5v14 M5 12h14',external:'M14 3h7v7 M21 3 10 14 M10 5H4v15h15v-6',back:'M20 12H4 m6-6-6 6 6 6',clock:'M12 8v5l3 2 M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0',box:'m3 7 9-4 9 4v11l-9 4-9-4z M3 7l9 5 9-5 M12 12v10',quote:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',eye:'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12 M9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0',info:'M12 8h.01 M12 11v6 M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const btn=(label,action,cls='outline',disabled=false,extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const tag=(text,color='')=>`<span class="tag ${color}">${esc(text)}</span>`;
const status=q=>({draft:'Draft',saved:'Saved · needs review',approved:'Approved',published:'Published'})[q?.status]||'Not started';
const statusTag=q=>tag(status(q),q?.status==='draft'?'orange':q?.status==='published'?'blue':'green');
const nav=[['overview','Overview','box'],['requirements','Requirements','quote'],['builder','Quotes','quote'],['explorer','Explorer','eye'],['publications','Published proposals','external'],['activity','Activity','chat']];
const SOURCE='Sample prices · January 29, 2025';
const GUIDE='Loading-guide design and fabrication allowance for irregular hardware parts.';
const QUESTION='Could you include a loading guide for our irregular hardware parts in Option B, and show the price and timing impact?';
const REPLY='Proposal V2 adds a $500 illustrative loading-guide engineering allowance to Option B and shows a one-week planning impact. Final geometry and application fit need PAC review of your sample parts and bags. Please review V2 and confirm the sample-review step.';
let record,runId='preview',viewOverride=null,selectedQuote='b',selectedMedia='loading',priceOverride=null,pdfUrl=null,pdfVersion=null,viewVersionOverride=null,requestSerial=0,toastTimer;
const seenRequests=new Map();
let storedKey=null,storedRaw=null,pdfRequest=0;
const VIDEO_URL='https://www.youtube.com/watch?v=nYCpXU1llI4';

const state=()=>record.state;
const latest=()=>state().publications.at(-1);
const created=()=>state().meta?.quotesCreated!==false;
const shownPrices=()=>priceOverride??state().meta?.priceVisible??true;
const price=v=>shownPrices()?money(v):'—';
const currentQuote=()=>state().quotes[selectedQuote];
function openBuilder(){if(!created()){const s=state();if(!(s.scope.width>0&&s.scope.length>0&&s.meta.requirementsConfirmed)){viewOverride='requirements';render();flash('Confirm the bag dimensions before preparing alternatives.');return;}if(!mutate(next=>{next.meta.quotesCreated=true;},'Quote alternatives prepared from the confirmed application.'))return;}viewOverride='builder';render();}

const currentVersion=()=>viewVersionOverride??(record.stepId==='B15'?1:record.stepId==='B14'?2:record.view?.version||latest()?.version||1);
const currentPublication=()=>state().publications.find(p=>p.version===currentVersion())||latest();
const comment=()=>state().comments[0];
const engineer=q=>q.engineering||{};
const lead=q=>q.planningLeadWeeks??(engineer(q).enabled&&engineer(q).leadWeeks==null?null:Number(q.baseLeadWeeks??6)+Number(engineer(q).leadWeeks||0));
const leadText=q=>lead(q)==null?'Pending':`${lead(q)} weeks`;
function scene(){if(viewOverride)return viewOverride;const id=record.stepId;
 if(['A06','A07','B16'].includes(id))return 'overview';if(['A08','A09','A10'].includes(id))return 'requirements';
 if(['A17','A18','A19','B07','B10','B11'].includes(id))return 'review';if(['A20','B12'].includes(id))return 'publication';
 if(['A21'].includes(id))return 'customer-needs';if(id==='A22')return 'customer-equipment';if(id==='A23')return 'customer-documents';
 if(['A24','B14','B15'].includes(id))return 'customer-compare';if(id==='B01')return 'customer-question';
 if(['B02','B13'].includes(id))return 'activity';if(['B03','B04'].includes(id))return 'explorer';return 'builder';}
function flash(message){clearTimeout(toastTimer);$('#guided-toast').textContent=message;$('#guided-toast').classList.add('visible');toastTimer=setTimeout(()=>$('#guided-toast').classList.remove('visible'),3500);}
function storageKey(){return `pac-guided-workspace-v1:${runId}`;}
function persist(){const key=storageKey();if(storedKey===key&&localStorage.getItem(key)!==storedRaw)throw Error('This rehearsal changed in another tab. Restart in a new rehearsal to keep both copies safe.');const raw=JSON.stringify({stepId:record.stepId,record,updatedAt:new Date().toISOString()});localStorage.setItem(key,raw);storedKey=key;storedRaw=raw;}
function mutate(operation,message){try{const next=clone(state());operation(next);const prior=record.state;record.state=next;try{persist();}catch(e){record.state=prior;throw e;}render();if(message)flash(message);return true;}catch(e){flash(e.message);return false;}}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function sampleFoot(){return `<div class="g-source">${SOURCE} · Planning times and engineering inputs are illustrative. Freight, tax and final terms require PAC confirmation.</div>`;}
function shell(body,section){const s=state();const active=section==='review'||section==='publication'?'builder':section;return `<div class="workspace"><aside class="sidebar"><a href="#overview" data-nav="overview" aria-label="PAC sales workspace">${image('pac-logo.png','PAC Machinery','brand')}</a><p class="workspace-label">Sales workspace</p><div class="deal-nav-heading"><strong>Harbor Components</strong><span>DEMO-042 · Rollbag R3200</span></div><nav aria-label="Deal workspace">${nav.map(([key,label,glyph])=>`<a href="#${key}" data-nav="${key}" class="nav-link ${key===active?'active':''}" ${key===active?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${key==='activity'&&s.comments.length&&!comment()?.reply?'<span class="nav-count">1</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="row"><span class="avatar">PA</span><div>PAC sales team<br><span>Demonstration workspace</span></div></div></div></aside><div class="app-body"><header class="topbar"><div class="breadcrumbs"><span>Deals</span>${icon('chevron')}<strong>Harbor Components</strong>${icon('chevron')}<span>${nav.find(n=>n[0]===active)?.[1]||'Quotes'}</span></div><div class="topbar-right">${tag('Illustrative case')}<span class="avatar">PA</span></div></header><main id="main" class="page g-page">${body}</main></div></div>`;}
function quoteMini(id){const q=state().quotes[id];return `<button class="g-quote-mini" data-action="quote" data-id="${id}"><span class="option-letter">${id.toUpperCase()}</span><span><strong>${esc(q.name)}</strong><small>Revision ${q.revision}</small></span>${statusTag(q)}<strong class="amount">${money(quoteTotal(q))}</strong>${icon('chevron')}</button>`;}
function overview(){const s=state(),p=latest(),finished=record.stepId==='B16';return shell(heading('Harbor Components','Hardware-kit packaging · Rollbag R3200',btn(created()?'Open quote builder':'Prepare quote alternatives','builder','primary'))+`<div class="deal-meta"><div><span>Primary contact</span><strong>Alex Morgan</strong><span>alex@harbor.example</span></div><div><span>Deal owner</span><strong>PAC sales team · demo</strong></div><div><span>Opportunity reference</span><strong>DEMO-042</strong><span>Prepared reference · no live CRM</span></div><div><span>Stage</span><strong>${finished?'Awaiting customer':p?'Proposal published':'Application review'}</strong></div></div><div class="g-overview-grid"><div><section class="deal-section"><div class="section-heading"><h2>Application brief</h2>${btn('View requirements','requirements','text-button small')}</div><h3>Irregular hardware kits, manually loaded.</h3><p class="body-copy">Compare standard hand loading with assisted bag opening. Confirm the bag, product and operating process before choosing a configuration.</p><dl class="g-facts"><div><dt>Bag dimensions</dt><dd>${s.scope.width?`${s.scope.width} × ${s.scope.length} in`:tag('To confirm','orange')}</dd></div><div><dt>Material</dt><dd>Polyethylene</dd></div><div><dt>Customer target</dt><dd>20 bags/min</dd></div><div><dt>Fit</dt><dd>Sample review required</dd></div></dl></section><section class="deal-section"><div class="section-heading"><h2>Quote alternatives</h2><span class="muted small-copy">One opportunity · separate revisions</span></div>${created()?['a','b'].map(quoteMini).join(''):`<div class="g-empty-inline"><h3>Confirm the bag dimensions first.</h3><p>Two alternatives will use the same confirmed application brief.</p>${btn('Complete requirements '+icon('arrow'),'requirements','text-button')}</div>`}</section>${finished?`<section class="deal-section"><div class="section-heading"><h2>Latest contact</h2>${tag('Awaiting customer','blue')}</div><div class="g-contact-row"><span class="avatar">PA</span><div><strong>Proposal reply · November 9, 2026</strong><p>V2 shared in the demonstration conversation. Waiting for the sample-review confirmation.</p></div></div></section>`:''}</div><aside class="g-deal-aside"><section class="next-action"><div class="section-heading"><h2>Next action</h2>${icon('clock')}</div><p>${finished?'Confirm representative sample parts and bags for the guide review.':esc(s.deal.nextAction||'Confirm the bag dimensions before quoting.')}</p><div class="next-action-owner">PAC sales team · demo${finished?' · Nov 12, 2026':''}</div>${finished?'<span class="small-copy muted">Illustrative follow-up date</span>':''}</section><figure class="g-machine-small">${image('r3200.png','Rollbag R3200 model reference')}<figcaption>Rollbag R3200 · Model reference</figcaption></figure>${p?`<div class="g-latest"><span class="eyebrow">Current customer offer</span><h2>Proposal V${p.version}</h2><p>A Rev ${p.quotes.a.revision} · B Rev ${p.quotes.b.revision}</p>${btn('Open proposal '+icon('arrow'),'customer','text-button')}</div>`:''}</aside></div>`, 'overview');}
function requirements(){const s=state(),proposed=record.stepId==='A09',confirmed=s.meta?.requirementsConfirmed||!!s.scope.width;return shell(heading('Application requirements','One brief for both quote alternatives.',confirmed?tag('Confirmed for quoting','green'):tag('Information needed','orange'))+`<div class="g-requirements-grid"><section>${record.stepId==='A08'?`<div class="g-blocker">${icon('info')}<div><strong>Bag dimensions are needed before quoting.</strong><p>The width determines whether assisted bag opening is compatible. The deal remains work in progress.</p></div></div>`:''}${proposed?`<div class="g-email"><div class="row spread"><strong>Customer clarification</strong>${tag('Prepared sample')}</div><p class="small-copy muted">Alex Morgan · Harbor Components</p><p>Hi PAC team — our pre-opened polyethylene bags are <strong>12 inches wide by 16 inches long</strong>. We load the hardware kits by hand. We would like to evaluate assisted bag opening. Our target is 20 bags per minute.</p><p>— Alex</p></div>`:`<div class="g-brief"><span class="eyebrow">Written scope</span><h2>Keep the application clear.</h2><p>Package irregular hardware kits in polyethylene bags using manual loading. Compare standard loading with assisted bag opening.</p></div>`}<div class="g-condition">${icon('info')}<p>Application fit remains subject to PAC review of representative bags and parts. The throughput is the customer’s target.</p></div></section><section class="g-requirements-fields"><div class="section-heading"><h2>${proposed?'Proposed update':'Application details'}</h2>${proposed?tag('Review before confirming','orange'):''}</div><form id="requirements-form"><div class="form-grid"><div><label for="bag-width">Bag width · in</label><input id="bag-width" name="width" type="number" min="1" value="${proposed?12:s.scope.width||''}" placeholder="To confirm"></div><div><label for="bag-length">Bag length · in</label><input id="bag-length" name="length" type="number" min="1" value="${proposed?16:s.scope.length||''}" placeholder="To confirm"></div><div class="full"><label for="bag-material">Material</label><input id="bag-material" name="material" value="Polyethylene"></div><div><label for="loading">Loading process</label><input id="loading" value="Manual" readonly></div><div><label for="target">Customer target</label><input id="target" name="target" value="20 bags/min"></div></div><button class="primary" type="submit">${confirmed?'Save requirements':'Confirm application facts'} ${icon('check')}</button><p class="small-copy muted">${confirmed?'Sales confirmed the supplied application facts.':'Values are confirmed by sales before quote creation.'}</p></form></section></div>`,'requirements');}
function quoteTabs(){return `<div class="quote-tabs" role="tablist" aria-label="Quote alternatives">${['a','b'].map(id=>{const q=state().quotes[id];return `<button class="quote-tab ${selectedQuote===id?'active':''}" role="tab" aria-selected="${selectedQuote===id}" data-action="quote" data-id="${id}"><span class="row"><span class="tab-letter">${id.toUpperCase()}</span><span><span class="tab-title">${esc(q.name)}</span><span class="tab-meta">Rev ${q.revision} · ${status(q)}</span></span></span><span class="amount">${price(quoteTotal(q))}</span></button>`;}).join('')}</div>`;}
function lineRows(q){return quoteLines(q).map(l=>`<tr><td><strong>${esc(l.name)}</strong><span>${esc(l.detail)}</span></td><td>${l.quantity}</td><td class="amount">${money(l.total)}</td></tr>`).join('');}
function summary(q){return `<section class="price-summary"><div class="summary-label">Equipment & service subtotal</div><div class="big-total amount">${price(quoteTotal(q))}</div><div class="summary-row"><span>Quantity</span><strong>${q.quantity} machine</strong></div><div class="summary-row"><span>Planning lead time</span><strong>${leadText(q)} <small>· illustrative</small></strong></div><div class="summary-row"><span>Quote</span><strong>Option ${q.id.toUpperCase()} · Rev ${q.revision}</strong></div><div class="summary-row summary-divider"><span>Review</span><strong>${status(q)}</strong></div><p class="source-note">${SOURCE}. Freight, tax and final terms require PAC confirmation.</p></section>`;}
function mediaPanel(q){return `<figure class="g-builder-media">${image(q.opener?'easy-load.jpg':'r3200.png',q.opener?'Easy Load Bag Opener option reference':'Rollbag R3200 model reference')}<figcaption>${q.opener?'Easy Load Bag Opener · Option reference':'Rollbag R3200 · Model reference'}</figcaption></figure>`;}
function option(name,key,amount,desc,q){return `<label class="g-option-row"><input type="checkbox" data-field="${key}" ${q[key]?'checked':''} ${q.status==='published'?'disabled':''}><span><strong>${name}</strong><small>${desc}</small></span><span class="amount">${price(amount)}</span></label>`;}
function engineeringFields(q){const e=engineer(q),set=e.amount!=null;return `<section class="g-engineering"><div class="section-heading"><h2>Engineering requirement</h2>${tag(set?'Estimate prepared':'Inputs pending',set?'blue':'orange')}</div><div class="g-engineering-scope"><strong>${esc(e.description||GUIDE)}</strong><p>${esc(e.reason||'Support repeatable manual positioning during loading. Final geometry requires PAC review of representative parts and bags.')}</p></div><div class="g-estimate-grid"><label>Labor hours<input data-engineering="laborHours" type="number" min="0" value="${e.laborHours??''}" placeholder="Pending"></label><label>Rate · USD / hour<input data-engineering="laborRate" type="number" min="0" value="${e.laborRate??''}" placeholder="Pending"></label><label>Materials · USD<input data-engineering="materials" type="number" min="0" value="${e.materials??''}" placeholder="Pending"></label></div><div class="g-estimate-total"><span>Internal engineering estimate</span><strong>${money(e.estimate)}</strong></div><div class="g-price-decision"><label>Proposed customer add-on · USD<input data-engineering="amount" type="number" min="0" value="${e.amount??''}" placeholder="Pending"></label><label>Additional lead time · weeks<input data-engineering="leadWeeks" type="number" min="0" value="${e.leadWeeks??''}" placeholder="Pending"></label></div><p class="small-copy muted">Illustrative hours, rate and allowance. Customer pricing is reviewed separately from the internal estimate.</p></section>`;}
function builder(){const q=currentQuote(),eng=engineer(q).enabled,changed=q.revision>0;return shell(heading('Quote builder','Compare clear alternatives for the same application.',btn(shownPrices()?'Hide prices':'Show prices','prices','ghost')+btn('Save changes','save','outline',q.status==='published')+btn('Review & publish '+icon('arrow'),'review','primary'))+quoteTabs()+`${changed?'<div class="g-revision-context">'+tag('Revision 1','blue')+'<span>From Alex’s question · Proposal V1 / Option B · Loading-guide scope</span></div>':''}<div class="builder-grid"><section class="editor ${eng?'g-engineering-editor':''}"><div class="scope-strip"><div><strong>Hardware-kit packaging</strong><p>12 × 16 in · Polyethylene · Manual loading · Target 20 bags/min</p></div>${btn('Requirements','requirements','text-button small')}</div>${eng?engineeringFields(q):`<div class="item-heading"><span>Machine & services</span><span>Price</span><span>Qty</span></div><div class="machine-line"><div class="machine-identity">${image('r3200.png','Rollbag R3200')}<div><strong>Rollbag R3200</strong><p>Automatic bagging system</p></div></div><span class="amount">${price(27580)}</span><span class="amount">1</span></div><div class="option-section"><div class="option-heading"><h3>Loading options</h3><span>Shape the application</span></div>${option('Easy Load Bag Opener','opener',6035,'Assisted bag opening · bags at least 10 in wide',q)}${option('Seal Flattener Fingers','fingers',1715,'Required with the Easy Load Bag Opener',q)}${q.opener&&!q.fingers?`<div class="dependency"><strong>Seal Flattener Fingers are required.</strong><p>The 12-inch bag meets the width rule. Add the companion fingers to complete this configuration.</p>${btn('Add required fingers','fingers','text-button small')}</div>`:''}</div><div class="option-section"><div class="option-heading"><h3>Start-up & training</h3><span>Charged once per quote</span></div>${option('On-Site Start-Up & Training','training',5480,'A separate service allowance included in this subtotal',q)}</div>`}<div class="g-save-row"><span>${statusTag(q)} <span class="small-copy muted">Option ${q.id.toUpperCase()} · Revision ${q.revision}</span></span>${btn(eng?'Save engineering resolution':'Save changes','save','primary',q.status==='published')}</div></section><aside class="media-summary">${mediaPanel(q)}${summary(q)}${eng?'<p class="g-source">The base machine, opener and fingers remain unchanged. The guide is an engineering allowance; no final guide drawing is issued.</p>':''}</aside></div>`,'builder');}
function reviewChecks(s,ids){
 const applicationReady=Number(s.scope.width)>0&&Number(s.scope.length)>0&&Boolean(String(s.scope.material||'').trim())&&Boolean(String(s.scope.target||'').trim());
 const compatible=ids.every(id=>{const q=s.quotes[id];return !q.opener||(q.fingers&&Number(s.scope.width)>=10);});
 const timingReady=ids.every(id=>lead(s.quotes[id])!==null);
 const rows=[
  {ready:applicationReady,text:applicationReady?'Application inputs recorded: bag, material and customer target.':'Complete the required application inputs.'},
  {ready:compatible,text:compatible?'Selected options satisfy the dependency and bag-width rules.':'Resolve the selected option dependencies and bag-width rules.'},
  {ready:null,text:'Review included services, exclusions and the dated sample price basis.'},
  {ready:timingReady,text:timingReady?'Illustrative planning time is recorded for each alternative.':'Confirm the missing engineering timing before approval.'},
  {ready:null,text:'Review sample-fit conditions and media coverage. Custom guide geometry still requires confirmation.'}
 ];
 return rows.map(row=>`<div class="${row.ready===false?'g-check-pending':row.ready===null?'g-check-prompt':''}">${icon(row.ready===true?'check':'info')}<span>${row.text}</span></div>`).join('');
}
function review(){const s=state(),rev=record.stepId.startsWith('B');const ids=rev?['b']:['a','b'];const p=latest();const errors=ids.flatMap(id=>validateQuote(s,id));const blocked=errors.length>0;return shell(heading(rev?'Review the revision':'Review before publication',rev?'Check the change against the original offer and application.':'Application, scope and commercial terms stay together.',tag(blocked?'Review blocked':ids.every(id=>['approved','published'].includes(s.quotes[id].status))?'Ready to publish':'Review in progress',blocked?'orange':'blue'))+`<div class="g-review-layout"><section>${blocked?`<div class="g-blocker">${icon('info')}<div><strong>${rev?'Complete the engineering inputs before approval.':'Complete the configuration before approval.'}</strong><p>${esc(errors[0]||record.expectedBlock?.messages?.[0]||'Resolve the missing inputs before approving this quote.')}${rev?' V1 remains available to the customer.':''}</p></div></div>`:''}${rev?`<div class="g-change-table"><div class="g-table-head"><strong>Change</strong><span>V1 · B Rev 0</span><span>Proposed · B Rev 1</span></div><div><strong>Loading-guide allowance</strong><span>Not included</span><span>${engineer(s.quotes.b).amount==null?'Pending':'$500 · illustrative'}</span></div><div><strong>Equipment & services</strong><span>$40,810</span><span>${money(quoteTotal(s.quotes.b))}</span></div><div><strong>Planning time</strong><span>6 weeks</span><span>${leadText(s.quotes.b)}</span></div><div><strong>Option A</strong><span>Rev 0 · $33,060</span><span>Unchanged</span></div></div><div class="g-review-rationale"><h3>Why this revision?</h3><p>${esc(engineer(s.quotes.b).reason||'The customer requested a loading guide for irregular hardware parts.')}</p><p class="small-copy muted">Final geometry and fit require PAC review of representative samples. Planning times are illustrative.</p></div>`:`<div class="g-review-scope"><span class="eyebrow">Confirmed application</span><h2>Irregular hardware kits</h2><dl class="g-facts"><div><dt>Bags</dt><dd>12 × 16 in</dd></div><div><dt>Material</dt><dd>Polyethylene</dd></div><div><dt>Loading</dt><dd>Manual</dd></div><div><dt>Target</dt><dd>20 bags/min</dd></div></dl></div>`}<div class="g-review-checks">${reviewChecks(s,ids)}</div></section><aside class="g-approval-stack">${ids.map(id=>{const q=s.quotes[id],approved=['approved','published'].includes(q.status),issues=validateQuote(s,id);return `<article class="g-approval"><div class="row spread"><span class="eyebrow">Option ${id.toUpperCase()} · Rev ${q.revision}</span>${statusTag(q)}</div><h2>${esc(q.name)}</h2><strong class="amount g-review-price">${money(quoteTotal(q))}</strong>${approved?`<div class="g-reviewer">${icon('check')}<div><strong>Demo reviewer</strong><small>Approved this saved revision · Nov 9</small></div></div>`:`<p class="small-copy muted">Ready for Demo reviewer.</p>${issues.length?'<p class="g-inline-error">'+esc(issues[0])+'</p>':''}${btn('Approve option '+id.toUpperCase(),'approve','primary',!!issues.length,`data-id="${id}"`)}`}</article>`;}).join('')}${btn('Publish proposal '+icon('arrow'),'publish','amber',!['a','b'].every(id=>['approved','published'].includes(s.quotes[id].status)&&!validateQuote(s,id).length))}<p class="small-copy muted">The approval belongs to this exact saved revision. Demonstration roles and dates are illustrative.</p></aside></div>${sampleFoot()}`,'review');}
function publication(){const p=latest();return shell(heading(`Proposal V${p?.version||1} is published.`,'A fixed customer version, built from the reviewed alternatives.',tag('Published','green'))+`<div class="g-publication-layout"><section><div class="g-publish-mark">${icon('check')}</div><h2>Your reviewed offer is ready.</h2><p class="g-publication-copy">The customer sees the application, equipment and alternatives together. Further work will create a new version.</p><div class="g-published-quotes">${['a','b'].map(id=>{const q=p.quotes[id];return `<div><span>Option ${id.toUpperCase()} · Revision ${q.revision}</span><strong>${esc(q.name)}</strong><b class="amount">${money(q.total)}</b></div>`;}).join('')}</div>${btn('Open customer proposal '+icon('external'),'customer','amber')}<p class="g-source">Published in this demonstration. No email has been sent.</p></section><aside><figure>${image('r3200.png','Rollbag R3200 model reference')}<figcaption>Rollbag R3200 · Model reference</figcaption></figure><div class="g-publication-meta"><span>Proposal V${p.version}</span><span>Harbor Components</span><span>Prepared November 9, 2026</span></div></aside></div>`,'publication');}
function activity(){const c=comment(),answered=!!c?.reply;return shell(heading('Customer activity','A conversation with its original offer in view.',tag(answered?'Answered · awaiting customer':'Needs response',answered?'blue':'orange'))+`<div class="g-activity-grid"><section class="g-thread"><div class="g-thread-context"><span>Proposal V${c?.version||1}</span><span>Option B · Revision ${c?.revision??0}</span><span>Loading area</span></div><div class="g-message"><span class="avatar">AM</span><div><div class="row spread"><strong>Alex Morgan</strong><span class="small-copy muted">Nov 9 · Sample customer</span></div><p>${esc(c?.text||QUESTION)}</p></div></div>${answered?`<div class="g-message g-reply"><span class="avatar">PA</span><div><div class="row spread"><strong>PAC sales team</strong>${tag('Reply recorded','green')}</div><p>${esc(typeof c.reply==='string'?c.reply:c.reply.text||REPLY)}</p>${btn('Review Proposal V2 '+icon('arrow'),'customer','text-button')}</div></div>`:`<div class="g-thread-next"><h3>Assess the guide with engineering.</h3><p>Keep the customer question beside the equipment reference and document the scope before revising the offer.</p>${btn('Inspect loading area '+icon('arrow'),'explorer','primary')}</div>`}<form id="reply-form" class="g-compose"><label for="reply">Reply in this proposal conversation</label><textarea id="reply" name="reply" placeholder="Explain the next step or clarify the proposed change."></textarea><button class="primary" type="submit">Record reply ${icon('arrow')}</button><span class="small-copy muted">Recorded locally in this demonstration.</span></form></section><aside class="g-activity-context"><h2>Follow-up</h2><dl><dt>Owner</dt><dd>PAC sales team · demo</dd><dt>Next action</dt><dd>${answered?'Confirm representative sample parts and bags.':'Assess loading-guide scope with engineering.'}</dd><dt>Original context</dt><dd>V1 / B Rev 0</dd><dt>Current offer</dt><dd>Proposal V${latest()?.version||1}</dd></dl>${btn('View original offer','version','outline',false,'data-version="1"')}</aside></div>`,'activity');}
function explorer(){const saved=state().findings?.length,media=selectedMedia==='opening'?['easy-load.jpg','Easy Load Bag Opener · Option reference']:['r3200-detail.jpg','R3200 loading & sealing area · Model detail'];return shell(heading('Equipment Explorer','A shared reference for the loading-guide question.',tag('PAC equipment photos','blue'))+`<div class="g-explorer-grid"><section><figure class="g-explorer-photo">${image(media[0],media[1])}<figcaption>${media[1]}<span>Reference photograph</span></figcaption></figure><div class="g-photo-tabs">${btn('Loading & sealing area','photo','',false,'data-id="loading" aria-pressed="'+(selectedMedia==='loading')+'"')}${btn('Assisted opening','photo','',false,'data-id="opening" aria-pressed="'+(selectedMedia==='opening')+'"')}</div><div class="g-reference-caption"><h3>Inspect the area behind the question.</h3><p>This photo shows existing equipment. The proposed custom guide will be assessed using the customer’s actual bags and parts.</p></div></section><aside class="g-finding-panel"><span class="eyebrow">Customer context</span><div class="g-finding-question"><strong>Alex Morgan</strong><p>${esc(comment()?.text||QUESTION)}</p><span class="small-copy muted">V1 · Option B · Rev 0</span></div>${saved?`<div class="g-saved-finding">${tag('Finding saved','green')}<h2>Loading-guide scope</h2><p>${esc(state().findings[0].note)}</p><div class="small-copy muted">PAC photo · C1 · V1 / B Rev 0</div>${btn('Create B revision '+icon('arrow'),'revise','primary')}</div>`:`<form id="finding-form"><label for="finding-title">Finding title</label><input id="finding-title" name="title" value="Loading-guide scope"><label for="finding-note">Observation</label><textarea id="finding-note" name="note">Customer requested a guide for irregular parts. Review representative bags and part samples before confirming guide geometry.</textarea><button type="submit" class="primary">Save finding ${icon('plus')}</button></form>`}<p class="g-source">Internal finding. Saving a reference does not change the quoted scope.</p></aside></div>`,'explorer');}
function publications(){return shell(heading('Published proposals','Earlier offers and their customer context stay intact.')+`<div class="publication-list">${[...state().publications].reverse().map((p,i)=>`<article class="publication-row"><div class="publication-identity"><span class="version-block">V${p.version}</span><div><h2>Proposal for Harbor Components</h2><p>November 9, 2026 · ${i?'Previous version':'Latest version'}</p></div></div><div class="publication-quotes"><span>A · Rev ${p.quotes.a.revision}<strong>${money(p.quotes.a.total)}</strong></span><span>B · Rev ${p.quotes.b.revision}<strong>${money(p.quotes.b.total)}</strong></span></div>${btn('Open proposal','version','outline',false,`data-version="${p.version}"`)}</article>`).join('')||'<p class="g-empty-inline">Save and approve both alternatives to publish the first customer version.</p>'}</div>`,'publications');}
function customerHeader(p,page){const tabs=[['needs','Your application'],['equipment','Equipment'],['compare','Compare options'],['documents','Documents'],['question','Conversation']];return `<header class="g-customer-header">${image('pac-logo.png','PAC Machinery','brand')}<div><strong>Prepared for Harbor Components</strong><span>Proposal V${p.version} · November 9, 2026</span></div></header><div class="g-customer-nav"><nav aria-label="Proposal sections">${tabs.map(([id,label])=>`<button data-action="customer-section" data-id="${id}" aria-current="${page===id?'page':'false'}">${label}${id==='question'&&state().comments.length?'<span class="g-count">'+state().comments.length+'</span>':''}</button>`).join('')}</nav><span class="tag">Illustrative proposal</span></div>`;}
function customerNeeds(p){return `<section class="g-customer-hero"><div><span class="eyebrow">Your application</span><h1>Better loading starts with your process.</h1><p>We understand you’re packing irregular hardware kits by hand. This proposal compares two loading approaches for the same Rollbag R3200.</p><dl class="g-customer-facts"><div><dt>Bag dimensions</dt><dd>${p.scope.width} × ${p.scope.length} in</dd></div><div><dt>Material</dt><dd>${esc(p.scope.material)}</dd></div><div><dt>Loading</dt><dd>Manual</dd></div><div><dt>Customer target</dt><dd>${esc(p.scope.target)}</dd></div></dl>${btn('See the equipment '+icon('arrow'),'customer-section','amber',false,'data-id="equipment"')}</div><figure>${image('r3200.png','Rollbag R3200 model reference')}<figcaption>Rollbag R3200 · Model reference</figcaption></figure></section><div class="g-customer-condition"><strong>Let’s confirm the fit.</strong><p>We’ll review representative bags and parts to confirm the application. The 20 bags/min figure is your target, not a guaranteed result.</p></div>`;}
function customerEquipment(){return `<div class="section-intro"><div><span class="eyebrow">Equipment & operation</span><h1>See the loading process.</h1></div><p>Understand the standard machine and the option behind assisted bag opening.</p></div><div class="g-customer-equipment"><section><figure class="g-operation-photo">${image(selectedMedia==='opening'?'easy-load.jpg':'r3200-detail.jpg',selectedMedia==='opening'?'Easy Load Bag Opener option reference':'PAC R3200 loading-area photograph')}<figcaption>${selectedMedia==='opening'?'Easy Load Bag Opener · Option reference':'R3200 loading area · Official PAC photograph'}</figcaption></figure><div class="g-photo-tabs">${btn('Loading process','photo','',false,'data-id="loading" aria-pressed="'+(selectedMedia==='loading')+'"')}${btn('Assisted opening','photo','',false,'data-id="opening" aria-pressed="'+(selectedMedia==='opening')+'"')}</div><div id="operation-media" class="g-media-status">Photo reference · operation video source available separately</div></section><aside><span class="eyebrow">The assisted-loading choice</span><h2>More support at the point of loading.</h2><p>The Easy Load Bag Opener supports bag opening during manual loading. Seal Flattener Fingers are the required companion option.</p><div class="g-equipment-rule"><strong>Bags at least 10 inches wide</strong><p>Your 12-inch bag meets the width rule. Actual application fit still needs a sample review.</p></div><p class="small-copy muted">Photos identify the model or option shown. They are not a generated assembly of your selected quote.</p>${btn('Compare the alternatives '+icon('arrow'),'customer-section','amber',false,'data-id="compare"')}</aside></div>`;}
function customerCompare(p){const revised=p.version>1,previous=record.stepId==='B15';return `${previous?`<div class="g-history-band"><strong>Previous offer · Proposal V1</strong><span>The original scope and values are preserved.</span>${btn('Return to V2','version','text-button small',false,'data-version="2"')}</div>`:revised?`<div class="g-history-band"><strong>Updated in V2</strong><span>Option B adds a $500 guide allowance and one illustrative planning week.</span>${btn('View V1','version','text-button small',false,'data-version="1"')}</div>`:''}<div class="section-intro"><div><span class="eyebrow">Your alternatives</span><h1>Same machine. Two loading choices.</h1></div><p>${revised?'The revised scope is clear; your original offer remains available.':'Choose the loading approach to discuss with your PAC team.'}</p></div><div class="g-comparison-grid">${['a','b'].map(id=>{const q=p.quotes[id],guide=engineer(q).enabled;return `<article class="g-offer ${id==='b'?'assisted':''}"><div class="row spread"><span class="eyebrow">Option ${id.toUpperCase()} · Revision ${q.revision}</span><span class="small-copy muted">Rollbag R3200</span></div><h2>${esc(q.name)}</h2><p class="g-offer-description">${id==='a'?'Standard manual loading into pre-opened bags on a roll.':'Easy Load Bag Opener with Seal Flattener Fingers.'}</p><dl><div><dt>Start-up & training</dt><dd>Priced service included</dd></div><div><dt>Loading-guide allowance</dt><dd>${guide?'$500 · illustrative':'Not included'}</dd></div><div><dt>Planning lead time</dt><dd>${leadText(q)} · illustrative</dd></div></dl><div class="g-offer-total"><span>Equipment & service subtotal</span><strong class="amount">${money(q.total)}</strong></div><div class="g-offer-actions">${btn('Ask about option '+id.toUpperCase(),'ask','amber',false,`data-id="${id}"`)}${btn('See line items','line-items','text-button',false,`data-id="${id}"`)}</div></article>`;}).join('')}</div><div class="g-comparison-bottom"><strong>Difference between A and B <span class="amount">${money(p.quotes.b.total-p.quotes.a.total)}</span></strong><p>${revised?'The assisted-loading equipment and guide allowance account for this difference.':'Easy Load Bag Opener $6,035 + Seal Flattener Fingers $1,715.'}</p></div><div id="customer-line-detail"></div><p class="g-source">${SOURCE}. Freight, tax and final terms require PAC confirmation. ${revised?'Guide geometry and fit remain subject to representative sample review.':''}</p>`;}
function customerDocuments(p){return `<div class="section-intro"><div><span class="eyebrow">Version-bound resources</span><h1>The documents behind your offer.</h1></div><p>These quote details belong to Proposal V${p.version}.</p></div><div class="g-document-grid"><section class="g-pdf-frame"><div class="g-document-toolbar"><strong>Quote V${p.version}.pdf</strong><a id="pdf-download" download="PAC-Harbor-Quote-V${p.version}.pdf" aria-disabled="true">Download PDF ${icon('download')}</a></div><div id="pdf-viewer" role="status"><div class="initial-loading">Preparing the saved quotation…</div></div></section><aside class="g-document-resources"><h2>Supporting references</h2><a href="https://www.pacmachinery.com/products/rollbag-r3200-and-r3200xl/" target="_blank" rel="noopener">PAC R3200 product information ${icon('external')}</a><button data-action="customer-section" data-id="equipment">Machine & option photographs ${icon('arrow')}</button><dl><dt>Customer</dt><dd>Harbor Components</dd><dt>Included revisions</dt><dd>A Rev ${p.quotes.a.revision} / B Rev ${p.quotes.b.revision}</dd><dt>Version</dt><dd>Proposal V${p.version}</dd></dl><p class="small-copy muted">The quote preserves the scope and values of this published version. No custom-guide drawing has been issued.</p></aside></div>`;}
function customerQuestion(p){const comments=state().comments.filter(c=>c.version===p.version);return `<div class="section-intro"><div><span class="eyebrow">Proposal V${p.version} · conversation</span><h1>Let’s work through the details.</h1></div><p>Your question stays with the option and version you reviewed.</p></div><div class="g-customer-conversation"><section>${comments.length?comments.map(c=>`<article class="g-customer-comment"><div class="row spread"><strong>Alex Morgan</strong>${tag(c.reply?'Answered · awaiting your review':'Question recorded',c.reply?'blue':'green')}</div><p>${esc(c.text)}</p><span class="small-copy muted">V${c.version} · Option ${c.alternative.toUpperCase()} · Rev ${c.revision} · ${esc(c.topic)}</span>${c.reply?`<div class="g-customer-reply"><strong>PAC sales team</strong><p>${esc(typeof c.reply==='string'?c.reply:c.reply.text||REPLY)}</p>${btn('Review V2 '+icon('arrow'),'version','text-button',false,'data-version="2"')}</div>`:''}</article>`).join(''):`<div class="g-question-empty"><h2>A conversation in context.</h2><p>Ask about handling, scope or timing. Your PAC team can respond and prepare a revision when needed.</p></div>`}</section><form id="customer-question-form"><label for="question-alternative">Related option</label><select id="question-alternative" name="alternative"><option value="b">Option B · ${esc(p.quotes.b.name)}</option><option value="a">Option A · ${esc(p.quotes.a.name)}</option></select><label for="customer-question">Question or requested change</label><textarea id="customer-question" name="question" placeholder="What would you like to discuss?"></textarea><button type="submit" class="amber">Record question ${icon('arrow')}</button><p class="small-copy muted">Saved in this demonstration conversation.</p></form></div>`;}
function customer(page){const p=currentPublication();if(!p)return shell(heading('No published proposal yet.','Save and approve the alternatives before publication.'),'publications');const body=page==='needs'?customerNeeds(p):page==='equipment'?customerEquipment(p):page==='documents'?customerDocuments(p):page==='question'?customerQuestion(p):customerCompare(p);return `<div class="g-customer">${customerHeader(p,page)}<main id="main" class="g-customer-main">${body}</main><footer class="g-customer-footer"><span>PAC Machinery · A solution around your process.</span><span>Proposal V${p.version} · Illustrative customer case</span></footer></div>`;}
function render({strict=false}={}){if(!record)return Promise.resolve();const sc=scene();$('#app').innerHTML=sc.startsWith('customer-')?customer(sc.replace('customer-','')):({overview,requirements,builder,review,publication,activity,explorer,publications}[sc]||overview)();document.body.dataset.scene=sc;document.body.dataset.step=record.stepId;document.title=`${sc.startsWith('customer-')?'Customer Proposal':'Sales Workspace'} · PAC Machinery`;if(sc==='customer-documents')return mountPdf(strict);if(sc==='customer-equipment')return mountMedia();return Promise.resolve();}
async function mountPdf(strict=false){const p=currentPublication(),version=p?.version,request=++pdfRequest;try{const {createProposalPdf}=await import('./pdf.mjs');const bytes=await createProposalPdf(p);if(scene()!=='customer-documents'||currentPublication()?.version!==version||request!==pdfRequest)return;if(!(bytes instanceof Uint8Array)||bytes.length<100)throw Error('The quotation file is incomplete.');if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));pdfVersion=version;$('#pdf-download').href=pdfUrl;$('#pdf-download').removeAttribute('aria-disabled');const {renderPdfPreview}=await import('./pdf-preview.mjs');if(scene()!=='customer-documents'||currentPublication()?.version!==version||request!==pdfRequest)return;await renderPdfPreview($('#pdf-viewer'),bytes,{version});}catch(e){if($('#pdf-viewer'))$('#pdf-viewer').innerHTML=`<div class="g-pdf-error"><h3>PDF could not be prepared.</h3><p>${esc(e.message)}</p>${btn('Retry document','pdf-retry','outline')}</div>`;if(strict)throw e;}}
async function mountMedia(){const target=$('#operation-media');if(!target)return;target.innerHTML=`<div class="g-video-actions">${btn('Play official operation video','operation-video','text-button small')}<a href="${VIDEO_URL}" target="_blank" rel="noopener">Open source ${icon('external')}</a></div><p>Official R3200 manual-loading demonstration. Installed options may differ.</p>`;}
function showOperationVideo(){const figure=$('.g-operation-photo');if(!figure)return;figure.innerHTML=`<iframe title="PAC R3200 manual-loading operation video" src="https://www.youtube-nocookie.com/embed/nYCpXU1llI4?autoplay=1&mute=1&rel=0&start=0&end=25" allow="autoplay; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><figcaption>R3200 manual loading · Official PAC video</figcaption>`;$('#operation-media').innerHTML=`<div class="g-video-actions">${btn('Use the equipment photo','photo','text-button small',false,'data-id="loading"')}<a href="${VIDEO_URL}" target="_blank" rel="noopener">Open official video ${icon('external')}</a></div><p>If playback is unavailable, continue with the equipment photo. This base-machine video does not confirm every quoted option.</p>`;}
function invalidate(q){if(q.status==='published')throw Error('Create a quote revision before editing published scope.');q.status='draft';q.approvedFingerprint=null;}
function readEngineeringValues(){
 const fields=[...document.querySelectorAll('input[data-engineering]')];
 if(!fields.length)return null;
 return Object.fromEntries(fields.map(input=>[input.dataset.engineering,input.value.trim()===''?null:Number(input.value)]));
}
function applyVisibleEngineering(q,values){
 if(!values)return;
 const changed=Object.entries(values).some(([key,value])=>q.engineering[key]!==value);
 if(!changed)return;
 invalidate(q);
 Object.assign(q.engineering,values);
 const e=q.engineering;
 e.estimate=[e.laborHours,e.laborRate,e.materials].every(value=>value!==null&&Number.isFinite(value))?e.laborHours*e.laborRate+e.materials:null;
}
$('#app').addEventListener('click',e=>{const navLink=e.target.closest('[data-nav]');if(navLink){e.preventDefault();viewOverride=navLink.dataset.nav;if(viewOverride==='builder'){openBuilder();return;}render();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(['overview','requirements','builder','explorer','activity','publications','review'].includes(a)){if(a==='builder'){openBuilder();return;}viewOverride=a;render();return;}
 if(a==='quote'){selectedQuote=b.dataset.id;viewOverride='builder';render();return;}if(a==='prices'){priceOverride=!shownPrices();render();return;}if(a==='photo'){selectedMedia=b.dataset.id;render();return;}
 if(a==='save'){const visibleEngineering=readEngineeringValues();mutate(s=>{const q=s.quotes[selectedQuote];applyVisibleEngineering(q,visibleEngineering);saveQuote(s,selectedQuote);},'Saved this quote revision.');return;}if(a==='fingers'){mutate(s=>{invalidate(s.quotes[selectedQuote]);s.quotes[selectedQuote].fingers=true;},'Required fingers added.');return;}
 if(a==='approve'){mutate(s=>{approveQuote(s,b.dataset.id);s.meta.approvalRecords??=[];const q=s.quotes[b.dataset.id];s.meta.approvalRecords.push({id:'manual-'+Date.now(),quoteId:b.dataset.id,revision:q.revision,actor:'Demo reviewer',at:new Date().toISOString(),fingerprint:q.approvedFingerprint,total:quoteTotal(q),sample:true});},'Approval recorded for the saved revision.');return;}
 if(a==='publish'){if(mutate(s=>publishProposal(s),'Customer version published locally.')){viewOverride='publication';render();}return;}
 if(a==='revise'){if(mutate(s=>reviseQuote(s,'b'),'Created a working revision of Option B.')){selectedQuote='b';viewOverride='builder';render();}return;}
 if(a==='customer'){record.view={...record.view,version:latest()?.version};viewOverride='customer-needs';render();return;}if(a==='customer-section'){viewOverride='customer-'+b.dataset.id;render();return;}
 if(a==='version'){viewVersionOverride=Number(b.dataset.version);viewOverride='customer-compare';render();return;}
 if(a==='ask'){selectedQuote=b.dataset.id;viewOverride='customer-question';render();const select=$('#question-alternative');if(select)select.value=selectedQuote;return;}
 if(a==='line-items'){const p=currentPublication(),q=p.quotes[b.dataset.id];$('#customer-line-detail').innerHTML=`<section class="g-expanded-lines"><h2>Option ${q.id.toUpperCase()} · ${esc(q.name)}</h2><table class="line-table"><thead><tr><th>Equipment & services</th><th>Qty</th><th>Amount</th></tr></thead><tbody>${lineRows(q)}</tbody></table><div class="line-total"><span>Subtotal · USD</span><strong>${money(q.total)}</strong></div></section>`;$('#customer-line-detail').scrollIntoView({behavior:'smooth',block:'nearest'});return;}
 if(a==='pdf-retry')mountPdf();if(a==='operation-video')showOperationVideo();
});
$('#app').addEventListener('change',e=>{if(e.target.dataset.field){const key=e.target.dataset.field;mutate(s=>{const q=s.quotes[selectedQuote];invalidate(q);q[key]=e.target.checked;});}if(e.target.dataset.engineering){const key=e.target.dataset.engineering;mutate(s=>{const q=s.quotes[selectedQuote];invalidate(q);q.engineering[key]=e.target.value===''?null:Number(e.target.value);const en=q.engineering;en.estimate=[en.laborHours,en.laborRate,en.materials].every(v=>v!=null)?en.laborHours*en.laborRate+en.materials:null;});}});
$('#app').addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form);if(form.id==='requirements-form'){const width=Number(fd.get('width')),length=Number(fd.get('length'));if(!(width>0&&length>0)){flash('Enter positive bag width and length.');return;}mutate(s=>{if(s.publications.length)throw Error('Use the quote revision workflow to change published application scope.');s.scope={...s.scope,width,length,material:fd.get('material'),target:fd.get('target')};s.meta.requirementsConfirmed=true;},'Application facts confirmed.');}
 if(form.id==='finding-form')mutate(s=>{addFinding(s,{kind:'photo',title:fd.get('title'),note:fd.get('note'),mediaKey:'sealing',alternative:'b'});},'Finding saved with this deal.');
 if(form.id==='reply-form'){const reply=String(fd.get('reply')||'').trim();if(!reply)return flash('Write a reply first.');mutate(s=>{const c=s.comments[0];if(!c)throw Error('There is no customer question to answer.');c.reply=reply;c.status='replied';},'Reply recorded in the demonstration.');}
 if(form.id==='customer-question-form')mutate(s=>addComment(s,{version:currentPublication().version,alternative:fd.get('alternative'),topic:'Loading area',author:'Alex Morgan · sample customer',text:fd.get('question')}),'Your question is recorded with this offer.');
});
async function enterStep(stepId,newRunId){const next=workspaceAt(stepId);assertWorkspaceStep(next);const prior=record,priorRun=runId;runId=String(newRunId||'preview').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,100)||'preview';record=next;selectedQuote=next.view?.quoteId||'b';viewOverride=null;viewVersionOverride=null;priceOverride=null;selectedMedia='loading';try{persist();}catch(e){record=prior;runId=priorRun;throw Error('The rehearsal could not be saved. '+e.message);}await render({strict:true});if(stepId==='A22')showOperationVideo();window.scrollTo(0,0);await new Promise(resolve=>requestAnimationFrame(()=>resolve()));return next;}
window.addEventListener('message',async e=>{if(e.source!==window.parent||e.origin!==location.origin||e.data?.type!=='pac-demo:step')return;const {stepId,requestId,runId:newRun}=e.data;const key=`${newRun}:${stepId}:${requestId}`;if(seenRequests.has(key)){e.source.postMessage(seenRequests.get(key),e.origin);return;}const serial=++requestSerial;try{await enterStep(stepId,newRun);if(serial!==requestSerial)return;const response={type:'pac-demo:complete',stepId,requestId};seenRequests.set(key,response);e.source.postMessage(response,e.origin);}catch(error){e.source.postMessage({type:'pac-demo:error',stepId,requestId,message:error.message},e.origin);}});
if(window.parent!==window)window.parent.postMessage({type:'pac-demo:ready',artifact:'workspace'},location.origin);
else {const params=new URLSearchParams(location.search);enterStep(params.get('step')||'A07',params.get('run')||'preview').catch(e=>{$('#app').innerHTML=`<div class="g-start-error"><h1>Unable to open this rehearsal.</h1><p>${esc(e.message)}</p></div>`;});}

window.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.target.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;if(window.parent!==window&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();window.parent.postMessage({type:e.key==='ArrowRight'?'pac-demo:next':'pac-demo:previous'},location.origin);}});
